test('parses thousands separators (checkout 500 regression)', () => {
  assert.strictEqual(parseAmount('2,450.50'), 245050);
  assert.strictEqual(parseAmount('1,299.00'), 129900);
  assert.strictEqual(parseAmount('1,234,567'), 123456700);
});
test('rejects malformed amounts with a descriptive error, not a TypeError', () => {
  for (const bad of ['abc', '', '1,23.00', '12,34,567', '1.234'])
    assert.throws(() => parseAmount(bad), /^Error: Invalid amount: /);
});
test('checkout handles comma-formatted prices', () => {
